-- Jornada extraordinaria del domingo y descanso de Citlali; no altera asistencias ni entregas anteriores.
begin;
select set_config('request.jwt.claim.sub',(select user_id::text from profiles where employee_number='003' and active),true);
create table if not exists staff_rest_calendar_history(employee_number text not null,valid_through date not null,weekday integer not null check(weekday between 0 and 6),primary key(employee_number,valid_through));
alter table staff_rest_calendar_history enable row level security;revoke all on staff_rest_calendar_history from public,anon,authenticated;
insert into staff_rest_calendar_history select employee_number,'2026-11-07',weekday from staff_rest_settings where employee_number='015' on conflict do nothing;
update staff_rest_settings set weekday=1 where employee_number='015';
update app_state st set value=(select jsonb_agg(case when c->>'id'='015' then c||jsonb_build_object('workdays',jsonb_build_array(0,2,3,4,5,6)) else c end) from jsonb_array_elements(st.value)c),updated_by=auth.uid(),updated_at=now() where key='xoxo.collaborators';
create or replace function staff_is_rest(person text,day date) returns boolean language sql stable security definer set search_path=public as $$select coalesce((select is_rest from staff_rest_exceptions where employee_number=person and staff_rest_exceptions.day=staff_is_rest.day),(select not(workdays @> to_jsonb(extract(dow from day)::integer)) from staff_workweek where employee_number=person),(select weekday=extract(dow from day)::integer from staff_rest_calendar_history where employee_number=person and day<=valid_through order by valid_through limit 1),(select weekday=extract(dow from day)::integer from staff_rest_settings where employee_number=person),false)$$;
revoke all on function staff_is_rest(text,date) from public,anon,authenticated;
insert into staff_rest_exceptions(employee_number,day,is_rest,request_id) select p,'2026-11-08',false,'direccion-domingo-2026-11-08' from unnest(array['008','007','014','015','010','011'])p on conflict(employee_number,day) do update set is_rest=false,request_id=excluded.request_id;
insert into app_state(key,value,updated_by) values('xoxo.workLocations','[]',auth.uid()) on conflict do nothing;
update app_state set value=(select coalesce(jsonb_agg(w),'[]') from jsonb_array_elements(value)w where not(w->>'date'='2026-11-08' and w->>'employeeId' in('008','007','014','015','010','011')))||(select jsonb_agg(jsonb_build_object('id','2026-11-08-'||p,'employeeId',p,'date','2026-11-08','location','Matriz','start','09:00','end','15:00','assignedById','003')) from unnest(array['008','007','014','015','010','011'])p),updated_by=auth.uid(),updated_at=now() where key='xoxo.workLocations';
do $$begin if to_regprocedure('sunday_base_cleaning_exit_time(text,date)') is null then alter function cleaning_exit_time(text,date) rename to sunday_base_cleaning_exit_time;end if;end $$;
revoke all on function sunday_base_cleaning_exit_time(text,date) from public,anon,authenticated;
create or replace function cleaning_exit_time(person text,day date) returns text language sql stable security definer set search_path=public as $$select case when day>='2026-11-08' and extract(dow from day)=0 and work_branch(person,day)='Matriz' then '15:00' else sunday_base_cleaning_exit_time(person,day) end$$;
revoke all on function cleaning_exit_time(text,date) from public,anon,authenticated;

create or replace function sunday_matriz_routine(rows jsonb,branch text,day date) returns jsonb language sql immutable set search_path=public as $$select case when branch<>'Matriz' or day<'2026-11-08' or extract(dow from day)<>0 then rows else coalesce((select jsonb_agg(case when lower(a->>'area') like '%aseo%' then a else a||jsonb_build_object('start',greatest(a->>'start','09:00'),'end',least(a->>'end','15:00'),'durationMinutes',extract(epoch from(least(a->>'end','15:00')::time-greatest(a->>'start','09:00')::time))/60) end) from jsonb_array_elements(rows)a where lower(a->>'area') like '%aseo%' or greatest(a->>'start','09:00')<least(a->>'end','15:00')),'[]') end$$;
revoke all on function sunday_matriz_routine(jsonb,text,date) from public,anon,authenticated;
do $$declare definition text;fn text;begin
 fn:=case when to_regprocedure('area_handover_base_capture()') is not null then 'area_handover_base_capture()' else 'staff_capture_today_plans()' end;definition:=pg_get_functiondef(fn::regprocedure);
 if position('sunday_matriz_routine' in definition)=0 then definition:=replace(definition,$old$  if branch<>'Sucursal Centro' then$old$,$new$  routine:=sunday_matriz_routine(routine,branch,capture_day);
  if branch<>'Sucursal Centro' then$new$);if position('sunday_matriz_routine' in definition)=0 then raise exception 'No se encontró el capturador de agenda';end if;execute definition;end if;
end $$;

with requested as(select value item from jsonb_array_elements($tasks$[{"id":"domingo-2026-11-08-008-1","employeeId":"008","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Revisar pedido de Tecnológico y notificar hilo Stihl","start":"09:30","end":"09:50","status":"Pendiente","priority":"Alta","notes":"Revisar el pedido de Tecnológico y confirmar si llegó el hilo amarillo cuadrado Stihl. Notificar al responsable del pedido la llegada y cantidad recibida, o la incidencia si está pendiente. Registrar la notificación y referencia del pedido. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true},{"id":"domingo-2026-11-08-008-2","employeeId":"008","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Revisar productos Lummi y notificar a Anubis","start":"09:50","end":"10:50","status":"Pendiente","priority":"Alta","notes":"Revisar físicamente los productos de Lummi contra el pedido y factura: códigos, cantidades, estado y faltantes. Documentar si llegó completo o hubo incidencias. Al terminar notificar a Anubis para ingresar factura y actualizar precios en Invewin. Sin esta revisión no se conoce la recepción real y se retrasa el alta. No disponer mercancía para venta hasta confirmar revisión, ingreso y precios. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true,"workflowKind":"lummi-review"},{"id":"domingo-2026-11-08-007-1","employeeId":"007","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Ingresar factura Lummi y actualizar precios en Invewin","start":"10:50","end":"11:20","status":"Pendiente","priority":"Alta","notes":"Esperar la revisión y notificación de Sabina. Dar de alta la factura y productos recibidos en Invewin y actualizar y comprobar los precios. Registrar el folio y confirmar al equipo que terminó para que Sabina pueda acomodar. No liberar los productos para venta hasta que el ingreso y precios estén confirmados. Si se retrasa esta etapa se retrasa el acomodo y la disponibilidad de venta; avisar al equipo. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true,"workflowKind":"lummi-entry","dependsOnTaskIds":["domingo-2026-11-08-008-2"]},{"id":"domingo-2026-11-08-008-3","employeeId":"008","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Acomodar y etiquetar productos Lummi: 80% exhibición y 20% almacén","start":"11:20","end":"13:20","status":"Pendiente","priority":"Alta","notes":"Esperar la confirmación de Anubis de factura y precios actualizados. Acomodar y etiquetar los productos exhibidos. Regla obligatoria: al menos 80% de las unidades en exhibición y como máximo 20% almacenadas; no invertir la proporción. Registrar cantidades reales exhibidas y almacenadas. Dejar productos identificados y con precio correcto. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true,"workflowKind":"lummi-display","dependsOnTaskIds":["domingo-2026-11-08-007-1"]},{"id":"domingo-2026-11-08-008-4","employeeId":"008","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Exhibición demostrativa de al menos dos productos Lummi","start":"13:20","end":"15:00","status":"Pendiente","priority":"Alta","notes":"Preparar al menos dos productos que puedan probarse, usarse o ejemplificar la solución que ofrecen. Dejarlos listos para demostración segura, identificados, etiquetados y con precio. Registrar los dos productos y la solución que demuestra cada uno. Mantener la regla de exhibición y almacenamiento. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true,"workflowKind":"lummi-demo","dependsOnTaskIds":["domingo-2026-11-08-008-3"]},{"id":"domingo-2026-11-08-007-2","employeeId":"007","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Actualizar estado de cuenta de proveedores","start":"11:20","end":"12:20","status":"Pendiente","priority":"Alta","notes":"Actualizar estados de cuenta de proveedores: facturas, abonos, saldos y vencimientos. Revisar diferencias y documentar los pendientes para Dirección. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true},{"id":"domingo-2026-11-08-007-3","employeeId":"007","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Inventariar y dejar disponibles promocionales de proveedores","start":"12:20","end":"15:00","status":"Pendiente","priority":"Alta","notes":"Reunir y dejar a la mano todos los promocionales disponibles de proveedores. Bajar llaveros y plumas. Preparar información detallada por proveedor, tipo de promocional, cantidad y ubicación. Registrar existencias y faltantes; coordinar con Rubén los regalos para clientes. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true},{"id":"domingo-2026-11-08-014-1","employeeId":"014","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Acomodar y limpiar góndola 1: cuatro pisos de exhibición","start":"09:30","end":"14:30","status":"Pendiente","priority":"Alta","notes":"Limpiar y acomodar la góndola 1 de químicos automotrices y juegos de autoclér. Contar los cuatro pisos de arriba hacia abajo. Piso 1 (más alto): únicamente químicos Würth y Wmax, con estética uniforme y limpia. Pisos 2 y 3: juegos de autoclér abiertos para mostrar el contenido y forrados para evitar sustracciones. Piso 4 (más bajo): químicos de gran tamaño de más de 2 litros y productos de otras marcas, distintos de Würth y Wmax. Dejar mueble y pasillos limpios, ordenados y libres de cajas y mercancía en el piso. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true},{"id":"domingo-2026-11-08-015-1","employeeId":"015","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Planear materiales audiovisuales de la siguiente semana","start":"09:30","end":"11:00","status":"Pendiente","priority":"Alta","notes":"Planear los materiales audiovisuales de la siguiente semana: productos, mensaje, guion, tomas, demostraciones, fechas y materiales necesarios. Registrar o enlazar el plan y los pendientes. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true},{"id":"domingo-2026-11-08-015-2","employeeId":"015","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Culminar exhibición","start":"11:00","end":"14:30","status":"Pendiente","priority":"Alta","notes":"Culminar la exhibición pendiente. Dejar productos acomodados, seguros, identificados y con precios correctos. Registrar qué se terminó y pendientes. El lunes es tu descanso; entregar el reporte semanal con evidencias antes de registrar salida. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true},{"id":"domingo-2026-11-08-015-3","employeeId":"015","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Entregar reporte semanal antes del descanso del lunes","start":"14:30","end":"14:55","status":"Pendiente","priority":"Alta","notes":"Entregar el reporte semanal con evidencias desde el apartado Reporte semanal del sistema, antes de la salida del domingo. Incluir resultados, pendientes y aperturas registradas en la sucursal donde se laboró. Esta tarea no sustituye la entrega real del reporte; el registro de salida conserva su validación. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":false},{"id":"domingo-2026-11-08-010-1","employeeId":"010","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Bajar, exhibir y etiquetar promociones de Buen Fin","start":"09:30","end":"15:00","status":"Pendiente","priority":"Alta","notes":"Bajar productos de promoción para rellenar al máximo los espacios: aspas para Oster, compresores de refrigerador, mangueras, suspensiones y relojes de lavadora. Acomodar y etiquetar con promocional de Buen Fin y precio correcto. Verificar disponibilidad y condiciones de promoción; registrar productos colocados y faltantes. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true},{"id":"domingo-2026-11-08-011-1","employeeId":"011","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Seleccionar productos para probar y preparar lista","start":"09:00","end":"10:30","status":"Pendiente","priority":"Alta","notes":"En Matriz, elaborar una lista de productos para probar y mostrar a clientes: código, nombre, utilidad, solución, accesorios necesarios y precauciones. Revisar disponibilidad y coordinar con jefes de área. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true},{"id":"domingo-2026-11-08-011-2","employeeId":"011","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Capacitación de los productos a mostrar","start":"10:30","end":"12:00","status":"Pendiente","priority":"Alta","notes":"Capacitarse en los productos seleccionados: funcionamiento, uso seguro, beneficios, solución al cliente, precio y cómo demostrar cada producto. Practicar las demostraciones y registrar dudas resueltas o pendientes. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true},{"id":"domingo-2026-11-08-011-3","employeeId":"011","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Acomodar mochila con productos y accesorios de demostración","start":"12:00","end":"13:30","status":"Pendiente","priority":"Alta","notes":"Acomodar la mochila con los productos y accesorios a mostrar. Verificar que el equipo esté completo y protegido, con una lista de contenido y pruebas de funcionamiento. No registrar ventas o entregas que no se realizaron. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true},{"id":"domingo-2026-11-08-011-4","employeeId":"011","assignedById":"003","date":"2026-11-08","branch":"Matriz","title":"Preparar regalos para clientes y verificar mochila","start":"13:30","end":"15:00","status":"Pendiente","priority":"Alta","notes":"Coordinar con Anubis los regalos disponibles para clientes: llaveros y plumas. Integrarlos a la mochila, registrar cantidades y revisar que productos y accesorios de demostración estén completos. Repasar la capacitación y dejar lista la mochila para mostrar soluciones a los clientes. Sólo para el domingo 8 de noviembre de 2026, Matriz, jornada 09:00–15:00. Primero recibir, atender o canalizar al cliente y después retomar la actividad. Coordinar cobertura y registrar pendientes.","currentStep":"Asignada","employeeComment":"","deliveryNote":"","supervisorComment":"","incidentNote":"","paused":false,"approvalStatus":"No requerida","requiresPhoto":false,"affectsEvaluation":true}]$tasks$::jsonb)) insert into daily_task_records(record_id,employee_number,branch,record_date,payload,updated_by) select item->>'id',item->>'employeeId','Matriz','2026-11-08',item||jsonb_build_object('assignedAt',now()),auth.uid() from requested on conflict(record_id) do nothing;
insert into assigned_task_dependencies(task_id,prerequisite_id,notice) values('domingo-2026-11-08-007-1','domingo-2026-11-08-008-2','Sabina debe concluir y confirmar la revisión física de Lummi antes del ingreso.') on conflict do nothing;
insert into assigned_task_dependencies(task_id,prerequisite_id,notice) values('domingo-2026-11-08-008-3','domingo-2026-11-08-007-1','Anubis debe confirmar factura y precios en Invewin antes del acomodo.') on conflict do nothing;
insert into assigned_task_dependencies(task_id,prerequisite_id,notice) values('domingo-2026-11-08-008-4','domingo-2026-11-08-008-3','Completar acomodo y etiquetado con regla 80/20 antes de las demostraciones.') on conflict do nothing;
notify pgrst,'reload schema';commit;
select employee_number,colaborador,inicio,fin,actividad from (select employee_number,(select v->>'name' from app_state s cross join lateral jsonb_array_elements(s.value)v where s.key='xoxo.collaborators' and v->>'id'=employee_number limit 1) colaborador,payload->>'start' inicio,payload->>'end' fin,payload->>'title' actividad from daily_task_records where record_date='2026-11-08' and record_id like 'domingo-2026-11-08-%')q order by employee_number,inicio;
